values ('les-lam-0201', 'mod-lam-02', 'course-laminado', 'tres-servicios', 1, 'Los 3 servicios a ofrecer', 'Perfilado clásico, perfilado con henna y Full Brows (laminado).', 'pdf', '[{"kind":"table","title":"Comparativa de servicios","headers":["Servicio","En qué consiste"],"rows":[["1 · Perfilado clásico","Visagismo y marcación correspondiente. Luego se depila con pinza y navaja."],["2 · Perfilado con henna","Perfilado clásico y, una vez terminado, se rellena el diseño de visagismo con henna."],["3 · Full Brows (laminado)","Primero el laminado, luego el visagismo, la depilación y por último la henna (opcional)."]]}]'::jsonb, '["Diferenciar los tres servicios","Saber qué incluye cada uno"]'::jsonb, '["Perfilado clásico","Perfilado con henna","Full Brows (laminado)"]'::jsonb, null, null)
