values ('les-lam-0203', 'mod-lam-02', 'course-laminado', 'paso-a-paso-perfilado', 3, 'Paso a paso del perfilado', 'El procedimiento completo, de la limpieza a la corrección final.', 'both', '[{"kind":"steps","title":"Procedimiento","items":["Limpiar muy bien la zona de las cejas con lash shampoo y retirar con un algodón humedecido.","Realizar la marcación con hilo y dibujar el diseño con la lapicera de gel blanca. Es importante mostrar el diseño a la clienta antes de comenzar.","Una vez aprobado el diseño, retirar todo el exceso de vello por fuera de la marcación blanca y, con la navaja, cuidadosamente retirar la pelusa.","Borrar toda la marcación con algodón y antibacterial o agua. Si es necesario, corregir."]}]'::jsonb, '["Ejecutar el perfilado en orden","Validar el diseño con la clienta"]'::jsonb, '["Limpieza","Marcación con hilo","Aprobación del diseño","Depilación y corrección"]'::jsonb, null, null)
