values ('les-lam-0301', 'mod-lam-03', 'course-laminado', 'henna-que-es', 1, 'Qué es la henna y cuánto dura', 'Materiales de henna y su duración en pelo y piel.', 'pdf', '[{"kind":"list","title":"Materiales","items":["Henna marrón y negra (se pueden mezclar entre sí)","Activador","Pincel biselado","Hisopos / micro hisopos / algodón"]},{"kind":"paragraph","text":"La duración depende de la frecuencia de lavado y del skincare de la clienta. Aproximadamente el color permanece en el PELO al menos 10 días y en la PIEL de 5 a 10 días."}]'::jsonb, '["Conocer los materiales de henna","Explicar la duración a la clienta"]'::jsonb, '["Materiales","Duración en pelo (~10 días)","Duración en piel (5–10 días)"]'::jsonb, null, null)
