values ('les-lam-0302', 'mod-lam-03', 'course-laminado', 'henna-aplicacion-tonos', 2, 'Aplicación y mezcla de tonos', 'Preparación, tiempos de acción y cómo lograr cada tono de castaño.', 'pdf', '[{"kind":"steps","title":"Cómo utilizar la henna","items":["Preparar en un vaso dappen una parte de henna y otra de activador (partes iguales).","Mezclar muy bien hasta obtener una mezcla homogénea.","Aplicar inmediatamente sobre la piel con el pincel.","Dejar actuar de 5 a 15 minutos (retirando el inicio antes) con algodón y agua."]},{"kind":"table","title":"Cómo mezclamos los tonos","headers":["Mezcla","Resultado"],"rows":[["Rubio y negro en partes iguales","Castaño medio"],["Más rubio y un poco de negro","Castaño claro"],["Más negro y un poco de rubio","Castaño oscuro"]]}]'::jsonb, '["Preparar y aplicar la henna","Mezclar tonos según el resultado buscado"]'::jsonb, '["Partes iguales henna + activador","5 a 15 minutos de acción","Mezcla de tonos"]'::jsonb, null, null)
