values ('les-lam-0401', 'mod-lam-04', 'course-laminado', 'laminado-que-es', 1, 'Qué es el laminado de cejas', 'Tratamiento semipermanente para dar forma, grosor y realzar el color.', 'pdf', '[{"kind":"paragraph","text":"El laminado de cejas es un tratamiento semipermanente con el que podemos dar forma a los vellos curvos o rebeldes que con un perfilado clásico no podríamos corregir. También se utiliza en cejas finas para generar grosor y dar una forma adecuada. Cabe destacar que realza el color natural del vello, haciéndolo ver más poblado y llamativo."}]'::jsonb, '["Explicar el laminado y sus beneficios","Detectar cuándo indicarlo"]'::jsonb, '["Da forma a vellos rebeldes que el perfilado no corrige","Genera grosor en cejas finas","Realza el color natural del vello"]'::jsonb, null, null)
