values ('les-lam-0402', 'mod-lam-04', 'course-laminado', 'laminado-paso-a-paso', 2, 'Paso a paso del laminado', 'Permanente, neutralizante y botox: tiempos y técnica.', 'both', '[{"kind":"steps","title":"Procedimiento","items":["Limpiar muy bien la zona de las cejas con lash shampoo y retirar con algodón humedecido.","Aplicar el paso N°1 (permanente) en toda la ceja, tratando de no tocar la piel, y dejar actuar de 10 a 15 minutos según el tipo de vello.","Retirar el paso N°1 con algodón seco y colocar el paso N°2 (neutralizante); dejar actuar el mismo tiempo que el anterior.","Retirar el paso N°2 con algodón humedecido, aplicar botox (indispensable), dejar actuar 10 minutos y retirar."]},{"kind":"callout","tone":"warning","title":"Tiempos según el vello","text":"Los tiempos de acción se ajustan al tipo de vello. El botox final es indispensable para nutrir y sellar el resultado."}]'::jsonb, '["Aplicar los pasos 1 y 2 con los tiempos correctos","Finalizar con botox"]'::jsonb, '["Paso 1 permanente","Paso 2 neutralizante","Botox indispensable"]'::jsonb, null, null)
