values ('les-lam-0501', 'mod-lam-05', 'course-laminado', 'cuidados-post-servicio', 1, 'Cuidados post servicio', 'Qué indicar a la clienta en las primeras 24 horas y después.', 'pdf', '[{"kind":"list","title":"Primeras 24 hs","items":["No lavar ni refregar la zona para evitar remover el producto de la piel o el vello.","No aplicar maquillaje ni ningún producto cosmético."]},{"kind":"list","title":"Luego de las 24 hs","items":["Evitar refregar la zona y evitar el agua caliente.","No utilizar productos cosméticos ni desmaquillantes en la zona."]}]'::jsonb, '["Entregar indicaciones claras de cuidado","Proteger el resultado"]'::jsonb, '["Primeras 24 h","Luego de 24 h"]'::jsonb, null, null)
