values ('les-lif-0103', 'mod-lif-01', 'course-lifting', 'el-pelo-componentes', 3, 'El pelo y sus componentes', 'Queratina, melanina, agua y lípidos: qué aporta cada uno.', 'pdf', '[{"kind":"paragraph","text":"El pelo es un filamento formado por una fibra de queratina, constituido por raíz y tallo. Se forma en un folículo piloso de la dermis y contiene agua, melanina, queratina y lípidos."},{"kind":"table","title":"Componentes","headers":["Componente","Función"],"rows":[["Queratina","Proteína fibrosa responsable de la estructura y resistencia del pelo. Aporta fuerza y rigidez."],["Melanina","Pigmento que da color al pelo y la piel. Su cantidad determina el color y aporta flexibilidad."],["Agua y lípidos","El agua da elasticidad; los lípidos mantienen el pelo suave y flexible. Fundamentales para su salud."]]}]'::jsonb, '["Comprender la composición del pelo","Relacionar componentes con el resultado"]'::jsonb, '["Queratina","Melanina","Agua y lípidos"]'::jsonb, null, null)
