values ('les-lif-0201', 'mod-lif-02', 'course-lifting', 'correcta-accion-quimicos', 1, 'Correcta acción de los químicos (Paso 1 y 2)', 'Qué hace cada paso sobre la cutícula, la queratina y la melanina.', 'pdf', '[{"kind":"steps","title":"Acción química","items":["Paso 1: fragmenta la cutícula y comienza a romper moléculas de queratina (perdemos fuerza en el pelo); luego sigue por la melanina, donde perdemos un poco de color.","Paso 2: se encarga de que el agente del paso 1 se detenga y, con ayuda del oxidante y del Ph, esas cutículas se vuelven a sellar."]}]'::jsonb, '["Entender la acción del paso 1","Entender el sellado del paso 2"]'::jsonb, '["Paso 1: fragmenta la cutícula","Paso 2: detiene y sella"]'::jsonb, null, null)
