values ('les-lif-0203', 'mod-lif-02', 'course-lifting', 'tiempos-de-accion', 3, 'Tiempos de acción: rápida, lenta y moderada', 'Cómo identificar los químicos por su tiempo de acción y su Ph.', 'pdf', '[{"kind":"paragraph","text":"Los químicos se identifican por sus tiempos de acción, que varían según su Ph."},{"kind":"table","title":"Tipos de acción","headers":["Acción","Tiempos"],"rows":[["Rápida","Cortos tiempos de acción (7-8-9-10-11-12-13)"],["Lenta","Tiempos largos (14-16-18-20-22)"],["Moderada","Intermedia, ni muy larga ni muy corta (entre 12 y 18)"]]}]'::jsonb, '["Clasificar químicos por tiempo de acción","Relacionar el Ph con la velocidad"]'::jsonb, '["Rápida","Lenta","Moderada"]'::jsonb, null, null)
