values ('les-lif-0301', 'mod-lif-03', 'course-lifting', 'herramientas-moldes', 1, 'Herramientas y moldes', 'El molde como instrumento principal para modificar el pelo.', 'pdf', '[{"kind":"paragraph","text":"Los moldes son el instrumento principal para la modificación del pelo. Lo importante es entenderlos para lograr cambios sin dificultades. Las herramientas base son: moldes, cepillos y herramienta."}]'::jsonb, '["Conocer las herramientas","Entender el rol del molde"]'::jsonb, '["Moldes","Cepillos","Herramienta"]'::jsonb, null, null)
