values ('les-lif-0302', 'mod-lif-03', 'course-lifting', 'curvas-formatos-moldes', 2, 'Curvas (C·U·D·LD) y formatos de moldes', 'Qué curva lograr según el molde, el ojo y la clienta.', 'pdf', '[{"kind":"paragraph","text":"Las diferentes curvas se logran según el molde que utilicemos y la aplicación del químico. Las más utilizadas son C, U, D y LD. La elección depende del ojo, el gusto de la clienta y el consejo profesional."},{"kind":"table","title":"Formatos de moldes","headers":["Formato","Efecto","Punto más alto"],"rows":[["Plano / semiplano","Full up","Abajo (S-M molde nube)"],["Semirredondo / curva U","Efecto muñeca","Por el medio (M1-M2 molde nube)"],["Redondo / curva C","Full curvatura","Arriba (L molde nube)"]]}]'::jsonb, '["Elegir la curva adecuada","Relacionar formato de molde con el efecto"]'::jsonb, '["Curvas C·U·D·LD","Plano / semiplano","Semirredondo / redondo"]'::jsonb, null, null)
