values ('les-lif-0401', 'mod-lif-04', 'course-lifting', 'cuidados-post-servicio-lifting', 1, 'Cuidados post servicio', 'Indicaciones para las primeras 12 y 24 horas.', 'pdf', '[{"kind":"list","title":"Primeras 12 hs","items":["No lavar ni refregar la zona para evitar remover el producto del pelo.","No aplicar maquillaje ni mojarlas."]},{"kind":"list","title":"Luego de las 24 hs","items":["Hidratarlas con keratina o serum.","Evitar máscaras a prueba de agua y usar desmaquillantes bifásicos que faciliten la remoción del maquillaje."]}]'::jsonb, '["Entregar indicaciones claras","Cuidar la durabilidad del lifting"]'::jsonb, '["Primeras 12 h","Luego de 24 h","Hidratación"]'::jsonb, null, null)
