values ('les-lif-0403', 'mod-lif-04', 'course-lifting', 'higiene-anmat-lifting', 3, 'Higiene, espacio de trabajo y ANMAT', 'Bioseguridad del espacio y verificación de productos aprobados.', 'pdf', '[{"kind":"list","title":"Higiene y espacio de trabajo","items":["Desinfectar siempre manos y materiales.","Los materiales descartables no se pueden volver a usar.","Zona de trabajo limpia y desinfectada.","Procurar el uso de barbijo.","Camilla con colchoneta o silla cómoda.","Ambiente con buen aroma."]},{"kind":"callout","tone":"warning","title":"Importante — ANMAT","text":"Al comprar cualquier producto debemos verificar que esté aprobado por la ANMAT para garantizar productos eficaces, seguros y de calidad."}]'::jsonb, '["Mantener un espacio seguro","Verificar aprobación ANMAT"]'::jsonb, '["Desinfección","Descartables","ANMAT"]'::jsonb, null, null)
